def find_holes_5x5(square):
    """Find 0 positions that are surrounded by 3s (4-connected neighbors are 3)"""
    holes = []
    for r in range(5):
        for c in range(5):
            if square[r][c] == 0:
                # Check if all 4 cardinal neighbors are 3
                neighbors = []
                if r > 0 and square[r-1][c] == 3:
                    neighbors.append(True)
                if r < 4 and square[r+1][c] == 3:
                    neighbors.append(True)
                if c > 0 and square[r][c-1] == 3:
                    neighbors.append(True)
                if c < 4 and square[r][c+1] == 3:
                    neighbors.append(True)
                if len(neighbors) == 4:
                    holes.append((r, c))
    return holes

def fill_squares(grid, sip, sicol):
    """Fill holes in a 5x5 square"""
    output = [row[:] for row in grid]
    for r in range(sip*5, sip*5+5):
        for c in range(sicol*5, sicol*5+5):
            sr, sc = r - sip*5, c - sicol*5  # local coordinates
            sq = []
            for i in range(5):
                row = []
                for j in range(5):
                    row.append(grid[sip*5+i][sicol*5+j])
                sq.append(row)

            if (sr, sc) in find_holes_5x5(sq):
                output[r][c] = 3
    return output

